-- ---------- Brand naming: one consistent English name across all texts ----------
update public.site_content set value = replace(value, 'IBM Institut Asia Malang', 'IBM Malang Asia Institute')
  where kind in ('text', 'richtext') and value like '%IBM Institut Asia Malang%' and content_key not like 'global.brand.%';
update public.site_content set value = replace(value, 'Institut Asia Malang', 'IBM Malang Asia Institute')
  where kind in ('text', 'richtext') and value like '%Institut Asia Malang%' and content_key not like 'global.brand.%';
update public.site_content set value = replace(value, 'IBM Institut Asia', 'IBM Asia')
  where kind in ('text', 'richtext') and value like '%IBM Institut Asia%' and content_key not like 'global.brand.%';
update public.site_content set value = replace(value, 'Logo IBM Malang Asia Institute', 'IBM Malang Asia Institute logo')
  where content_key = 'global.brand.logo_alt';

