    insert into public.news (title, excerpt, image_url, published_at, is_featured, link_url, slug, content) values
      ('IBM Class of 2026 Student Orientation Officially Opens', 'New students join an orientation programme introducing the campus, the curriculum, and the Double Degree pathway.', 'https://placehold.co/720x450/173671/EBB213?text=Featured+News', '2026-08-12', true, '', 'ibm-class-of-2026-student-orientation', '<p>Sample article — replace it with your real news through the content column of the news table.</p><h2>Programme highlights</h2><p>Summarise what happened, who was involved, and why it matters to students.</p><ul><li>First point</li><li>Second point</li><li>Third point</li></ul><blockquote>A quote from a speaker can be placed here.</blockquote><p>You can also add a <a href="admission.html">link</a> to another page.</p>'),
      ('Guest Lecture: Export Strategies for SMEs', 'An export practitioner shares the steps to enter overseas markets, from legal requirements to logistics.', 'https://placehold.co/640x400/2A52A0/FFFFFF?text=News+2', '2026-08-05', false, '', 'guest-lecture-export-strategies-for-smes', 'Sample article — replace it with your real news through the content column of the news table.

