-- ---------- Official partner logo: reuse the Trent logo already set on the About page ----------
update public.partners p set logo_url = c.value
  from public.site_content c
  where c.content_key = 'about.glimpse.partner_logo' and c.value <> '' and p.is_official and p.name = 'Trent Global College'
    and p.logo_url like 'https://placehold.co/%';
